window.docContents[221].resolve({"/5___-Representations-of-finite-groups___-Further-results/5___1___-Frobenius-Schur-indicator/Frobenius-Schur-indicator/#Chapter5___Definition5___1___4":{"contents":"Definition 5.1.4. The Frobenius-Schur indicator FS(V) of an irreducible representation V is 0 if it is of complex type, 1 if it is of real type, and -1 if it is of quaternionic type.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.1. Frobenius-Schur indicator\tFrobenius-Schur indicator","header":"Frobenius-Schur indicator","id":"/5___-Representations-of-finite-groups___-Further-results/5___1___-Frobenius-Schur-indicator/Frobenius-Schur-indicator/#Chapter5___Definition5___1___4"},"/5___-Representations-of-finite-groups___-Further-results/5___24___-Problems/Invariant-polynomials-on-matrix-tuples-are-generated-by-traces/#Chapter5___Problem5___24___2":{"contents":"Problem 5.24.2. Let R_{k,N} be the algebra of polynomials on the space of k-tuples of complex N \\times N matrices X_1, \\ldots, X_k, invariant under simultaneous conjugation. An example of an element of R_{k,N} is the function T_w := \\operatorname{Tr}(w(X_1, \\ldots, X_k)), where w is any finite word on a k-letter alphabet. Show that R_{k,N} is generated by the elements T_w.\n\nHint: Consider invariant functions that are of degree d_i in each X_i, and realize this space as a tensor product \\bigotimes_i S^{d_i}(V \\otimes V^*). Then embed this tensor product into (V \\otimes V^*)^{\\otimes n} = \\operatorname{End}(V)^{\\otimes n}, and use the Schur-Weyl duality to get the result.\n\n\n\n","context":"Introduction to Representation Theory\t5. Representations of finite groups: Further results\t5.24. Problems\tInvariant polynomials on matrix tuples are generated by traces","header":"Invariant polynomials on matrix tuples are generated by traces","id":"/5___-Representations-of-finite-groups___-Further-results/5___24___-Problems/Invariant-polynomials-on-matrix-tuples-are-generated-by-traces/#Chapter5___Problem5___24___2"}});
